-- AA Toolkit (protected build). Source is encrypted; this decrypts and runs it in memory.
-- Paste into Potassium and execute after the game has loaded. Do not edit.
local A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function b64(value)
    value=value:gsub('[^'..A..'=]','')
    return (value:gsub('.',function(char)
        if char=='='then return ''end
        local index=A:find(char,1,true)-1
        local bits=''
        for shift=5,0,-1 do bits=bits..(math.floor(index/2^shift)%2==1 and '1'or'0')end
        return bits
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(bits)
        if #bits~=8 then return ''end
        local byte=0
        for index=1,8 do if bits:sub(index,index)=='1'then byte=byte+2^(8-index)end end
        return string.char(byte)
    end))
end
local xor3
if bit32 then xor3=function(a,b,c) return bit32.bxor(a,b,c) end
else xor3=function(a,b,c)
    local r,m=0,1
    for _=1,8 do
        local s=(a%2+b%2+c%2)%2
        r=r+s*m; m=m*2
        a=math.floor(a/2); b=math.floor(b/2); c=math.floor(c/2)
    end
    return r
end end
local K=b64('UuziTcwgt5kirTEq1ykBrsx4351jBgp1pS1kSdjRL0uirJJ2tdj/rtrmgEqYYKn0')
local D=b64('')
local kl,out=#K,{}
for i=1,#D do
    out[i]=string.char(xor3(string.byte(D,i),string.byte(K,(i-1)%kl+1),((i-1)*7)%256))
end
local run,err=loadstring(table.concat(out),'AA_Toolkit_Protected')
assert(run,'Protected loader failed to decode: '..tostring(err))
return run()
